// === Tab: mySketch ===
// 空間をグリッドで分割してそれぞれに点を取って
// それでvoronoiやってみる感じ。
// グリッド内の小数部分であれして、そのセルの周囲計9つについて
// 点を調べる感じ・・んー。

// 参考：The Book of Shaders:https://thebookofshaders.com/12/?lan=jp

// せっかくだからヴォロノイ境界まで行きたい。
// 最も近い2つの距離に対して差を取ると失敗する。
// そうではなくて最も近い2つの点を取る。
// もし境界上ならそれら2点の垂直2等分線上にあるはず。
// ヴォロノイ分割は成功しているのでいずれかのセルには入って
// いるわけで、その上で最も近い2点なので、別の点というのは
// そのセルに隣接したセルということになり、だからその境界に近いはず。
// で、その垂直2等分線との距離を2点の情報から計算で出せばいいって感じ。
// あとはそれが0.05以下ならOKとか適当にバリデーション掛ける感じです。
// 詳しくは→http://www.iquilezles.org/www/articles/voronoilines/voronoilines.htm

let myShader;

let properFrameCount = 0;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
// random2関連
"const vec2 r_vector_1 = vec2(127.1, 311.7);" +
"const vec2 r_vector_2 = vec2(269.5, 183.3);" +
"const float r_coeff = 43758.5453123;" +
// 2Dランダムベクトル(-1.0～1.0)
"vec2 random2(vec2 st){" +
"  vec2 v = vec2(0.0);" +
"  v.x = sin(dot(st, r_vector_1)) * r_coeff;" +
"  v.y = sin(dot(st, r_vector_2)) * r_coeff;" +
"  return -1.0 + 2.0 * fract(v);" + // -1.0～1.0に正規化
"}" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getHSB(float r, float g, float b){" +
"    vec3 c = vec3(r, g, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"void main(void){" +
"  vec2 st = gl_FragCoord.xy * 0.5 / min(u_resolution.x, u_resolution.y);" +
// スケール変換。マウスで調整する(3.0～10.0)
"  st *= 3.0 + 7.0 * clamp(u_mouse.x / u_resolution.x, 0.0, 1.0);" +
// ずらしもやってみるか
"  st += vec2(u_time * 1.2, u_time * 1.6);" +
// グリッドの場所(i_st)とそこにおける座標(f_st)を取得。
// これシンプレックスでもいけるんかな・・(シンプレックスヴォロノイズ）
"  vec2 i_st = floor(st);" +
"  vec2 f_st = fract(st);" +
// 最も近い点との距離を割り出す。2番目も欲しいのでvec2にする。
"  vec2 m_dist = vec2(4.0);" +
// 最も近い点と次に近い点を求めたい。
"  vec2 cl_a = vec2(0.0);" +
"  vec2 cl_b = vec2(0.0);" +
"  for(float x = -1.0; x <= 1.0; x += 1.0){" +
"    for(float y = -1.0; y <= 1.0; y += 1.0){" +
// neighborはi_stを含む周囲9つのグリッド点のどれかとの差。
"      vec2 neighbor = vec2(x, y);" +
// 周囲9つの点それぞれについて、その点におけるランダムvec2を取得する。
// これは毎回同じ値が出る（ランダムではあっても）。
"      vec2 point = random2(i_st + neighbor);" +
// それに対して次のようにu_timeを絡ませることで点が移動しているように
// 見せかけることができる。
"      point = neighbor + 0.5 + 0.5 * sin(u_time + 2.0 * pi * point);" +
// pointとf_stの距離が全部で9つ出てくるので最小値を探す。
"      vec2 diff = point - f_st;" +
"      float dist = length(diff);" +
"      if(dist < m_dist.x){" +
"        m_dist.y = m_dist.x;" +
"        m_dist.x = dist;" +
"        cl_b = cl_a;" +
"        cl_a = point;" +
"      }else if(dist < m_dist.y){" +
"        m_dist.y = dist;" +
"        cl_b = point;" +
"      }" +
"    }" +
"  }" +
// cl_aとcl_bから内積計算で境界との距離を計算する
"  float distWithBorder = abs(dot(f_st - 0.5 * (cl_a + cl_b), normalize(cl_b - cl_a)));" +
// hue, sat, blを決める。
// hueはマウスの上下移動で0.55～0.85くらいで変化させる感じで。
"  float hue = 0.85 + 0.3 * clamp(u_mouse.y / u_resolution.y, 0.0, 1.0);" +
// satは点の中心ほど1.0に近くなるように設定
//"  float sat = max(0.0, 1.0 - m_dist.x);" +
"  float sat = atan(distWithBorder, m_dist.x) * 0.6366197;" +
// ただし点の中心では白くしたい。これはm_distが0.02以下の時に・・
"  sat *= step(0.03, m_dist.x);" +
// bl.
"  float bl = 1.0;" +
// 境界付近ではdistWithborderが0に近いので黒くする
"  bl *= smoothstep(0.0, 0.02, distWithBorder);" +
"  gl_FragColor = vec4(getHSB(hue, sat, bl), 1.0);" +
"}";

function setup(){
  createCanvas(1112, 834, WEBGL);
  angleMode(DEGREES);
  myShader = createShader(vs, fs);
  shader(myShader);
  //noLoop();
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", properFrameCount / 120);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
  properFrameCount++;
}

function mousePressed(){
  noLoop();
}

function mouseReleased(){
  loop();
}

// 境界との距離と最近点との距離が等しい時に0.5で
// 境界に近い時に0.0で最近点に近い時に1.0になるようにしたいわけ。
// atanを使えばいいかも。atan(distWithBorder, m_dist.x)すると・・
// 0.0からイコールでpi/4なって近い時pi/2だからpi/2で割ればいい。
// やっぱ比だときれいにならないな・・・

